--DS d_ds_job_price_hdr
SELECT job_price_hdr.job_price_hdr_uid,            job_price_hdr.job_no,            job_price_hdr.job_description,            job_price_hdr.company_id,            job_price_hdr.customer_id,            job_price_hdr.sales_loc_id,            job_price_hdr.contract_no,            job_price_hdr.contact_id,            job_price_hdr.start_date,            job_price_hdr.end_date,            job_price_hdr.ship_to_id,            job_price_hdr.approved,            job_price_hdr.cancelled,            job_price_hdr.taker,            job_price_hdr.po_no,            job_price_hdr.row_status_flag,            job_price_hdr.date_last_modified,            job_price_hdr.date_created,            job_price_hdr.last_maintained_by,     job_price_hdr.corp_address_id,     job_price_hdr.salesrep_id,     job_price_hdr.currency_line_uid,     job_price_hdr.currency_conversion,     job_price_hdr.consignment_flag,     job_price_vendor.vendor_id,     job_price_hdr.contract_type_cd 
FROM job_price_hdr  LEFT JOIN job_price_vendor 
ON (job_price_vendor.job_price_hdr_uid = job_price_hdr.job_price_hdr_uid) 
WHERE  job_price_hdr.contract_no = 'MSC' AND job_price_hdr.company_id = '1' AND job_price_hdr.corp_address_id = 49889 AND ( (job_price_hdr.row_status_flag <> 700) ) 